import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Table-Formatting.md","filePath":"manual-en/CTABLES-Table-Formatting.md","lastUpdated":1785684581000}'),s={name:"manual-en/CTABLES-Table-Formatting.md"};function r(i,e,d,c,l,_){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h4 id="_15-7-7-table-formatting" tabindex="-1">15.7.7 Table Formatting <a class="header-anchor" href="#_15-7-7-table-formatting" aria-label="Permalink to &quot;15.7.7 Table Formatting&quot;">​</a></h4><pre><code>/FORMAT
    [MINCOLWIDTH={DEFAULT _|_ _width_}]
    [MAXCOLWIDTH={DEFAULT _|_ _width_}]
    [UNITS={POINTS _|_ INCHES _|_ CM}]
    [EMPTY={ZERO _|_ BLANK _|_ _string_}]
    [MISSING=_string_]
</code></pre><p>The <code>FORMAT</code> subcommand, which must precede the first <code>TABLE</code> subcommand, controls formatting for all the output tables. <code>FORMAT</code> and all of its settings are optional.</p><p>Use <code>MINCOLWIDTH</code> and <code>MAXCOLWIDTH</code> to control the minimum or maximum width of columns in output tables. By default, with <code>DEFAULT</code>, column width varies based on content. Otherwise, specify a number for either or both of these settings. If both are specified, <code>MAXCOLWIDTH</code> must be greater than or equal to <code>MINCOLWIDTH</code>. The default unit, or with <code>UNITS=POINTS</code>, is points (1/72 inch), or specify <code>UNITS=INCHES</code> to use inches or <code>UNITS=CM</code> for centimeters. PSPP does not currently honor any of these settings.</p><p>By default, or with <code>EMPTY=ZERO</code>, zero values are displayed in their usual format. Use <code>EMPTY=BLANK</code> to use an empty cell instead, or <code>EMPTY=&quot;_string_ &quot;</code> to use the specified string.</p><p>By default, missing values are displayed as ‘.’, the same as in other tables. Specify <code>MISSING=&quot;_string_ &quot;</code> to instead use a custom string.</p>`,6)])])}const T=t(s,[["render",r]]);export{u as __pageData,T as default};
